var i=`1401-hokey-pokey-ice-cream`;var a=`world-1401`;var o=`NZ`;var t=`oceania`;var r=6;var m=412;var s={en:`Hokey Pokey Ice Cream`,ua:`Морозиво хокі-покі`};var l={en:`New Zealand vanilla ice cream studded with crunchy golden-syrup honeycomb. A no-churn, egg-free home version.`,ua:`Новозеландське ванільне морозиво з хрусткими шматочками карамелі на золотому сиропі. Домашня версія без яєць і морозивниці.`};var u=[{en:`Line a tray with parchment. Heat caster sugar and golden syrup over medium-low heat until melted and bubbling, about 4–5 minutes; do not stir aggressively.`,ua:`Застеліть деко пергаментом. Нагрівайте дрібний цукор і золотий сироп на помірно слабкому вогні до розчинення й появи бульбашок приблизно 4–5 хвилин; не перемішуйте надмірно.`,t:[`caramelizing-sugar`],m:5,i:[[`caster-sugar`,70,`g`],[`golden-syrup`,45,`g`]]},{en:`Remove from heat, quickly stir in baking soda once, and immediately pour the foaming honeycomb onto parchment. Keep clear of the hot sugar.`,ua:`Зніміть із вогню, швидко один раз умішайте соду та негайно вилийте спінену карамель на пергамент. Бережіться гарячого цукру.`,t:[`mixing`],m:2,i:[[`baking-soda`,5,`g`]]},{en:`Cool the honeycomb completely for about 30 minutes, then break into pea-sized shards.`,ua:`Повністю остудіть карамель приблизно 30 хвилин, тоді поламайте на невеликі шматочки.`,t:[`chopping`],m:30,i:[]},{en:`Whip the cold cream until soft peaks form. Fold in condensed milk and vanilla without deflating the mixture.`,ua:`Збийте холодні вершки до м’яких піків. Обережно вмішайте згущене молоко та ваніль, не осаджуючи масу.`,t:[`whipping-cream`,`folding-in`],m:10,i:[[`whipping-cream`,500,`ml`],[`sweetened-condensed-milk`,280,`g`],[`vanilla-extract`,7,`ml`]]},{en:`Fold in most of the honeycomb, reserving a little for topping. Transfer to a covered freezer container and freeze until firm, at least 6 hours.`,ua:`Умішайте більшість карамелі, трохи залиште для посипання. Перекладіть у закритий контейнер і заморожуйте до повного застигання не менше 6 годин.`,t:[`no-churn-freezing`],m:360,i:[]},{en:`Let soften for 5 minutes, scoop and sprinkle with the remaining honeycomb.`,ua:`Дайте морозиву пом’якшитися 5 хвилин, розкладіть по порціях і посипте залишеною карамеллю.`,t:[`garnishing`],m:5,i:[]}];var c={slug:i,id:a,country:`NZ`,region:t,servings:6,minutes:412,title:s,text:l,steps:u};export{o as country,c as default,a as id,m as minutes,t as region,r as servings,i as slug,u as steps,l as text,s as title};